import {NPX_POINTS} from './npx-biopsy.js';
const svg=(content,label,viewBox='0 0 480 320')=>`<svg viewBox="${viewBox}" role="img" aria-label="${label}" xmlns="http://www.w3.org/2000/svg">${content}</svg>`;
export function npxTool(id){
  const tool=id==='packing'?'<path d="M61 24l49 6 2 39-50-5z" fill="#efe5cd" stroke="#c1b79d" stroke-width="2"/><path d="M70 31l29 4M68 39l33 4M68 48l34 4M69 57l26 3" stroke="#c8c1a9" stroke-dasharray="3 3"/>':id==='cup'?'<g fill="none" stroke="#a7bebd" stroke-width="5" stroke-linecap="round"><path d="M45 67l85-37m-85 26l85-20"/><ellipse cx="35" cy="71" rx="12" ry="9"/><ellipse cx="35" cy="52" rx="12" ry="9"/><path d="M130 30q16-13 18 0-5 10-18 6"/></g><path d="M128 28l2 10" stroke="#f1ede0" stroke-width="2"/>':'<path d="M45 73l85-44" stroke="#ad9b79" stroke-width="5"/><path d="M123 34l14-8" stroke="#f2eee2" stroke-width="14" stroke-linecap="round"/>';
  return svg(`<rect width="170" height="95" rx="8" fill="#d5dfd3"/>${tool}`,id==='packing'?'止血綿':id==='cup'?'Biopsy cup':'棉棒','0 0 170 95');
}
export function npxDrape(t){return svg(`<defs><linearGradient id="npxcloth" x2="1" y2="1"><stop stop-color="#77a797"/><stop offset="1" stop-color="#416d62"/></linearGradient></defs><rect width="480" height="320" rx="12" fill="#c1cbb9"/><rect x="112" y="30" width="256" height="270" rx="25" fill="#728b81"/><path d="M162 182q78-37 156 0v118H162" fill="#b9b7a4"/><ellipse cx="240" cy="105" rx="45" ry="53" fill="#d3ae97"/><path d="M197 81q0-45 43-42 44-2 44 42" fill="#4a5350"/><path d="M225 110h30m-15-9v16" stroke="#b58e7b" stroke-width="2"/>${t.drapes.map(i=>i===0?'<path d="M103 34h90v185h-90z" fill="url(#npxcloth)"/>':i===1?'<path d="M287 34h90v185h-90z" fill="url(#npxcloth)"/>':'<path d="M104 171h272v129H104z" fill="url(#npxcloth)"/>').join('')}<path d="M126 281h54m120 0h54" stroke="#adc6b2" stroke-width="2"/><text x="24" y="297" fill="#4f6e65" font-size="11" letter-spacing="2">13 / NPX BIOPSY</text>`,'病人與三處鋪單位置的簡化示意');}
export function npxEndoscope(t){
  const p=NPX_POINTS[t.mass],x=p.x*4.8,y=p.y*3.2,sampled=t.specimen,stopped=t.hemostasis;
  const folds=NPX_POINTS.map((q,i)=>i===t.mass?'':`<path d="M${q.x*4.8-29} ${q.y*3.2+10}q26-37 56-8q-28-13-55 6" fill="#b9847c" stroke="#d3a49a" stroke-width="3"/>`).join('');
  return svg(`<defs><radialGradient id="npxmucosa"><stop stop-color="#c49c89"/><stop offset=".7" stop-color="#8b645d"/><stop offset="1" stop-color="#3d373a"/></radialGradient><radialGradient id="npxedge"><stop offset=".72" stop-color="#112e32" stop-opacity="0"/><stop offset="1" stop-color="#112e32"/></radialGradient></defs><rect width="480" height="320" rx="12" fill="#17373c"/><ellipse cx="240" cy="160" rx="204" ry="145" fill="url(#npxmucosa)"/><path d="M200 67q35 26 83-4M171 264q69-30 141-4" stroke="#d1ab99" stroke-width="9" opacity=".4" fill="none"/>${folds}<g transform="translate(${x} ${y})"><path d="M-36 5q-12-30 7-39 8-18 26-8 25-5 32 17 21 13 8 32-4 22-31 19-22 14-37-7z" fill="${sampled?'#ac7771':'#be8580'}" stroke="#d4a098" stroke-width="3"/>${Array.from({length:7},(_,i)=>`<circle cx="${-19+(i%3)*17}" cy="${-20+Math.floor(i/3)*17}" r="${5+i%3}" fill="#d7a69a" opacity=".55"/>`).join('')}${sampled?`<ellipse cx="5" cy="2" rx="9" ry="7" fill="${stopped?'#ae8377':'#a45956'}"/>`:''}${sampled&&!stopped?'<path d="M15 19q-7 8 0 11 7-3 0-11M-13 17q-6 7 0 10 6-3 0-10" fill="#b5726b"/>':''}</g>${t.stage==='sample'?`<path d="M350 300L${x+11} ${y+16}m12 7L375 300" stroke="#b6c7c4" stroke-width="7" fill="none"/><path d="M${x+11} ${y+16}q-20-2-15-16m26 23q-2-20-16-18" stroke="#d5deda" stroke-width="5" fill="none"/>`:''}${t.stage==='hemostasis'?`<path d="M370 300L${x+13} ${y+13}" stroke="#ae9d7e" stroke-width="7"/><path d="M${x+19} ${y+19}l-16-16" stroke="#ebe7da" stroke-width="20" stroke-linecap="round"/>`:''}<ellipse cx="240" cy="160" rx="204" ry="145" fill="url(#npxedge)"/><text x="22" y="26" fill="#c2d7ca" font-size="11" letter-spacing="2">NPX / ENDOSCOPIC VIEW</text><circle cx="438" cy="23" r="4" fill="#adbea4"/>`,'簡化鼻咽內視鏡：平順皺摺與一處不規則隆起');
}
export function npxSpecimen(t){return svg(`<rect width="480" height="320" rx="12" fill="#cad5c5"/><ellipse cx="239" cy="276" rx="91" ry="13" fill="#9dad9d" opacity=".45"/><rect x="164" y="89" width="150" height="177" rx="18" fill="#e7ebdc" fill-opacity=".7" stroke="#8ba79e" stroke-width="3"/><rect x="154" y="55" width="170" height="47" rx="9" fill="#58796c"/><path d="M169 67h140m-140 9h140m-140 9h140" stroke="#79988b" stroke-width="3"/><path d="M217 244q13-17 34-8l11 13-15 7-25-4z" fill="#bc8f81"/><rect x="181" y="131" width="116" height="85" rx="3" fill="#f3efdf" stroke="#b7bca9"/><path d="M196 151h83m-83 13h66m-66 13h75" stroke="#a1afa4" stroke-width="3"/><text x="239" y="203" text-anchor="middle" fill="#547265" font-size="18">${t.labeled?'✓ NPX':'?'}</text><text x="240" y="304" text-anchor="middle" fill="#57756a" font-size="11" letter-spacing="2">一塊檢體 / 鼻咽</text>`,'檢體瓶、單一檢體及待核對標籤');}
